def countRoutesThroughRequired(grid):
    m, n = len(grid), len(grid[0])
    w = n + 2                              # border of blocked cells so that no bounds checks are needed
    blocked = [True] * ((m + 2) * w)
    required = [False] * ((m + 2) * w)
    need = 0
    for r in range(m):
        for c in range(n):
            v = grid[r][c]
            i = (r + 1) * w + c + 1
            blocked[i] = v == -1
            if v == 1:
                start = i
            elif v == 2:
                end = i
            elif v == 3:
                required[i] = True
                need += 1
    steps = (w, -w, 1, -1)

    def go(cell, left):
        if cell == end:
            return 1 if left == 0 else 0
        blocked[cell] = True
        total = 0
        for d in steps:
            nxt = cell + d
            if not blocked[nxt]:
                total += go(nxt, left - 1 if required[nxt] else left)
        blocked[cell] = False
        return total

    return go(start, need)
